public long fib(long n, long p) {
    long[][] result = {{1, 0}, {0, 1}}; // identity
    long[][] base = {{1, 1}, {1, 0}};   // M
    while (n > 0) {
        if ((n & 1) == 1) result = multiply(result, base, p);
        base = multiply(base, base, p);
        n >>= 1;
    }
    return result[0][1]; // F(n)
}

private long[][] multiply(long[][] A, long[][] B, long p) {
    long[][] C = new long[2][2];
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            long sum = 0;
            for (int k = 0; k < 2; k++) {
                sum = (sum + A[i][k] * B[k][j]) % p; // mod after each multiply
            }
            C[i][j] = sum;
        }
    }
    return C;
}

