def fib(self, n: int, p: int) -> int:
    result = [[1, 0], [0, 1]]  # identity
    base = [[1, 1], [1, 0]]    # M
    while n > 0:
        if n & 1:
            result = self.multiply(result, base, p)
        base = self.multiply(base, base, p)
        n >>= 1
    return result[0][1]  # F(n)

def multiply(self, A: list[list[int]], B: list[list[int]], p: int) -> list[list[int]]:
    C = [[0, 0], [0, 0]]
    for i in range(2):
        for j in range(2):
            C[i][j] = (A[i][0] * B[0][j] + A[i][1] * B[1][j]) % p
    return C

